INSERT INTO public.challenges (slug, title, track, topic, difficulty, xp, brief, starter_code, hints, tests) VALUES
('gcse-seq-greeting','Say hello','gcse','sequencing',1,10,'Read a name from the input and print `Hello, <name>!`','name = input()\n','["Use input() to read a line","Use an f-string: print(f\"Hello, {name}!\")"]','[{"stdin":"Ada","expect":"Hello, Ada!"},{"stdin":"Zac","expect":"Hello, Zac!"}]'),
('gcse-seq-area','Rectangle area','gcse','sequencing',1,10,'Read a width then a height (two lines, whole numbers) and print the area.','','["int(input()) converts text to a number"]','[{"stdin":"3\n4","expect":"12"},{"stdin":"10\n7","expect":"70"}]'),
('gcse-seq-swap','Swap two values','gcse','sequencing',2,15,'Read two lines. Print them back in the opposite order, one per line.','','["You can store both then print in reverse"]','[{"stdin":"cat\ndog","expect":"dog\ncat"},{"stdin":"1\n2","expect":"2\n1"}]'),
('gcse-seq-total','Shopping total','gcse','sequencing',2,15,'Read a price (decimal) and a quantity (whole number). Print the total cost rounded to 2 decimal places.','','["float(input()) for decimals","Use round(total, 2)"]','[{"stdin":"2.5\n4","expect":"10.0"},{"stdin":"1.99\n3","expect":"5.97"}]'),
('gcse-sel-oddeven','Odd or even','gcse','selection',1,10,'Read a whole number. Print `Even` if it is even, otherwise `Odd`.','','["Use the modulus operator %","n % 2 == 0 means even"]','[{"stdin":"4","expect":"Even"},{"stdin":"7","expect":"Odd"},{"stdin":"0","expect":"Even"}]'),
('gcse-sel-grade','Exam grade','gcse','selection',2,20,'Read a mark out of 100. Print `Grade 9` for 80+, `Grade 7` for 60-79, `Grade 4` for 40-59, otherwise `Grade 1`.','','["Use if / elif / else","Check the highest boundary first"]','[{"stdin":"85","expect":"Grade 9"},{"stdin":"60","expect":"Grade 7"},{"stdin":"41","expect":"Grade 4"},{"stdin":"12","expect":"Grade 1"}]'),
('gcse-sel-login','Password check','gcse','selection',2,20,'Read a password. Print `Access granted` if it equals `secret123`, otherwise `Access denied`.','','["Compare strings with =="]','[{"stdin":"secret123","expect":"Access granted"},{"stdin":"hello","expect":"Access denied"}]'),
('gcse-sel-largest','Largest of three','gcse','selection',3,25,'Read three whole numbers on separate lines and print the largest.','','["Compare them with if statements, or build a list"]','[{"stdin":"3\n9\n5","expect":"9"},{"stdin":"10\n2\n1","expect":"10"},{"stdin":"1\n2\n8","expect":"8"}]'),
('gcse-sel-leap','Leap year','gcse','selection',3,25,'Read a year. Print `Leap` if it is a leap year, otherwise `Not leap`.','','["Divisible by 4 and not by 100, unless also divisible by 400"]','[{"stdin":"2024","expect":"Leap"},{"stdin":"1900","expect":"Not leap"},{"stdin":"2000","expect":"Leap"},{"stdin":"2023","expect":"Not leap"}]'),
('gcse-it-count','Count to N','gcse','iteration',1,10,'Read a whole number N and print every number from 1 to N, one per line.','','["for i in range(1, n+1):"]','[{"stdin":"3","expect":"1\n2\n3"},{"stdin":"1","expect":"1"}]'),
('gcse-it-times','Times table','gcse','iteration',2,20,'Read a number N. Print its times table from 1 to 10 in the form `3 x 1 = 3`.','','["Loop with range(1, 11)","Use an f-string"]','[{"stdin":"2","expect":"2 x 1 = 2\n2 x 2 = 4\n2 x 3 = 6\n2 x 4 = 8\n2 x 5 = 10\n2 x 6 = 12\n2 x 7 = 14\n2 x 8 = 16\n2 x 9 = 18\n2 x 10 = 20"}]'),
('gcse-it-sum','Sum until zero','gcse','iteration',3,25,'Keep reading whole numbers until the user enters 0. Print the total of all numbers entered (not counting the 0).','','["A while True loop with a break works well"]','[{"stdin":"3\n4\n0","expect":"7"},{"stdin":"0","expect":"0"},{"stdin":"10\n-5\n5\n0","expect":"10"}]'),
('gcse-it-stars','Star triangle','gcse','iteration',3,25,'Read a number N and print a triangle of stars: row 1 has 1 star, row N has N stars.','','["Nested loop, or use \"*\" * i"]','[{"stdin":"3","expect":"*\n**\n***"},{"stdin":"1","expect":"*"}]'),
('gcse-it-guess','Validation loop','gcse','iteration',3,25,'Keep reading numbers until one is between 1 and 10 inclusive. Print `Valid: <number>` for that one. Print `Try again` for each invalid number first.','','["while not valid: ...","Print the error inside the loop"]','[{"stdin":"20\n0\n5","expect":"Try again\nTry again\nValid: 5"},{"stdin":"1","expect":"Valid: 1"}]'),
('gcse-list-avg','List average','gcse','lists',2,20,'Read a line of numbers separated by spaces. Print their average rounded to 1 decimal place.','','["Use input().split()","Convert each item with int()"]','[{"stdin":"1 2 3 4","expect":"2.5"},{"stdin":"10 20","expect":"15.0"}]'),
('gcse-list-max','Highest score','gcse','lists',2,20,'Read a line of scores separated by spaces. Print the highest score.','','["max() works on a list of numbers"]','[{"stdin":"4 19 3","expect":"19"},{"stdin":"7","expect":"7"}]'),
('gcse-list-search','Linear search','gcse','lists',3,25,'Read a line of words separated by spaces, then read a search word. Print the index of the word (starting at 0) or `Not found`.','','["Loop with a counter, or use a for loop over range(len(items))"]','[{"stdin":"cat dog fish\ndog","expect":"1"},{"stdin":"cat dog\nbird","expect":"Not found"}]'),
('gcse-list-reverse','Reverse a list','gcse','lists',2,20,'Read a line of words separated by spaces. Print them in reverse order on one line, separated by spaces.','','["Slicing with [::-1] reverses a list","\" \".join(items) joins them back up"]','[{"stdin":"a b c","expect":"c b a"},{"stdin":"one","expect":"one"}]'),
('gcse-list-2d','Seating grid','gcse','lists',4,30,'Read a number of rows R, then R lines each containing numbers separated by spaces. Print the total of every number in the grid.','','["Build a list of lists","Use a nested loop to add them up"]','[{"stdin":"2\n1 2\n3 4","expect":"10"},{"stdin":"1\n5 5 5","expect":"15"}]'),
('gcse-str-upper','Shout it','gcse','strings',1,10,'Read a line of text and print it in capital letters.','','["Strings have an .upper() method"]','[{"stdin":"hello there","expect":"HELLO THERE"}]'),
('gcse-str-count','Count vowels','gcse','strings',3,25,'Read a line of text and print how many vowels (a, e, i, o, u) it contains. Ignore capitals.','','["Lowercase the text first","Loop over each character"]','[{"stdin":"Hello World","expect":"3"},{"stdin":"xyz","expect":"0"}]'),
('gcse-str-palindrome','Palindrome check','gcse','strings',3,25,'Read a word. Print `Yes` if it reads the same backwards, otherwise `No`.','','["word[::-1] reverses a string"]','[{"stdin":"racecar","expect":"Yes"},{"stdin":"python","expect":"No"}]'),
('gcse-func-square','Write a function','gcse','functions',2,20,'Write a function called `square(n)` that returns n squared. Then read a number and print `square(n)`.','def square(n):\n    pass\n','["Use return, not print, inside the function"]','[{"stdin":"5","expect":"25"},{"stdin":"0","expect":"0"}]'),
('gcse-func-isprime','Prime subprogram','gcse','functions',4,35,'Write a function `is_prime(n)` that returns True or False. Read a number and print `Prime` or `Not prime`.','def is_prime(n):\n    pass\n','["Numbers below 2 are not prime","Test divisors from 2 up to n-1"]','[{"stdin":"7","expect":"Prime"},{"stdin":"9","expect":"Not prime"},{"stdin":"1","expect":"Not prime"}]'),
('gcse-file-write','Write to a file','gcse','files',3,25,'Read a line of text, write it to a file called `notes.txt`, then read the file back and print its contents.','','["open(\"notes.txt\", \"w\") to write","open(\"notes.txt\") to read"]','[{"stdin":"remember this","expect":"remember this"}]'),
('gcse-file-lines','Count file lines','gcse','files',4,30,'Read a number N, then N lines of text. Save them all to `data.txt` (one per line), then reopen the file and print how many lines it contains.','','["Write each line with a \\n on the end","readlines() gives you a list"]','[{"stdin":"3\na\nb\nc","expect":"3"},{"stdin":"1\nhello","expect":"1"}]'),
('alevel-rec-factorial','Recursive factorial','alevel','recursion',3,30,'Write a recursive function `factorial(n)` and print factorial of the number read from input.','def factorial(n):\n    pass\n','["Base case: n <= 1 returns 1","Otherwise return n * factorial(n-1)"]','[{"stdin":"5","expect":"120"},{"stdin":"0","expect":"1"}]'),
('alevel-rec-fib','Fibonacci sequence','alevel','recursion',4,35,'Read N and print the first N Fibonacci numbers (starting 0, 1) separated by spaces.','','["Recursion or iteration both work","Watch the first two terms"]','[{"stdin":"5","expect":"0 1 1 2 3"},{"stdin":"1","expect":"0"}]'),
('alevel-sort-bubble','Bubble sort','alevel','algorithms',3,30,'Read a line of numbers separated by spaces. Sort them ascending using bubble sort and print them separated by spaces. Do not use sorted() or .sort().','','["Nested loops with a swap","Repeat until no swaps happen"]','[{"stdin":"5 2 9 1","expect":"1 2 5 9"},{"stdin":"3","expect":"3"}]'),
('alevel-search-binary','Binary search','alevel','algorithms',4,35,'Read a line of ascending numbers, then a target. Print the index found by binary search, or `Not found`.','','["Track low and high pointers","mid = (low + high) // 2"]','[{"stdin":"1 3 5 7 9\n7","expect":"3"},{"stdin":"2 4 6\n5","expect":"Not found"}]'),
('alevel-oop-class','Define a class','alevel','oop',3,30,'Create a class `Student` with a constructor taking name and mark, and a method `passed()` returning True when mark >= 40. Read a name then a mark and print `Pass` or `Fail`.','class Student:\n    pass\n','["Use __init__(self, name, mark)","self.mark stores the value"]','[{"stdin":"Ada\n55","expect":"Pass"},{"stdin":"Bob\n12","expect":"Fail"}]'),
('alevel-oop-inherit','Inheritance','alevel','oop',4,35,'Create a class `Animal` with a method `speak()` returning `...`, and a subclass `Dog` overriding it to return `Woof`. Read a word: if it is `dog` print a Dog speaking, otherwise print an Animal speaking.','','["class Dog(Animal): inherits","Override speak in the subclass"]','[{"stdin":"dog","expect":"Woof"},{"stdin":"cat","expect":"..."}]'),
('alevel-ds-stack','Stack operations','alevel','data structures',4,35,'Read a line of push values separated by spaces, then a number P. Push all values onto a stack, pop P items, then print the remaining stack from bottom to top separated by spaces (print `Empty` if none remain).','','["A Python list works as a stack","append() pushes, pop() pops"]','[{"stdin":"1 2 3 4\n2","expect":"1 2"},{"stdin":"5\n1","expect":"Empty"}]'),
('alevel-ds-queue','Queue simulation','alevel','data structures',4,35,'Read a line of names, then a number D. Add all names to a queue, dequeue D of them, and print who is now at the front (`Empty` if nobody).','','["A queue is first in, first out","pop(0) removes the front"]','[{"stdin":"ann bob cid\n1","expect":"bob"},{"stdin":"ann\n1","expect":"Empty"}]');